import { test } from 'node:test'

import { Vfs, buildVfsBundle, loadNodeModules } from '../stasis/src/vfs-bundle.js'
import { lockfile } from './vfs-bundle-github.helper.js'

const yarnLockfile = ['# THIS IS AN AUTOGENERATED FILE. DO NOT EDIT THIS FILE DIRECTLY.', '# yarn lockfile v1', '', ''].join('\n')

// Its own process: the machine's libc is detected once and cached, so no other test may detect it first.

const project = () => {
  const vfs = new Vfs()
  vfs.mkdir('/src', { recursive: true })
  vfs.writeFile('/package.json', '{"name":"p","version":"1.0.0"}\n')
  vfs.writeFile('/pnpm-lock.yaml', lockfile('.'))
  vfs.writeFile('/src/a.js', '')
  return vfs
}

test('pnpm: libc defaults to the machine\'s, detected only when none is given and for this os', async (t) => {
  const vfs = project()
  await t.assert.rejects(loadNodeModules({ vfs, packageManager: 'pnpm', libc: 'bionic' }), /^TypeError: loadNodeModules: libc must be one of 'glibc', 'musl', 'unknown'/u)
  await t.assert.rejects(buildVfsBundle({ vfs, packageManager: 'pnpm', libc: 'bionic', entries: ['src/a.js'] }), /^TypeError: buildVfsBundle: libc must be one of/u)
  const getReport = t.mock.method(process.report, 'getReport')
  await Promise.all(['glibc', 'musl', 'unknown'].map(async (libc) => t.assert.equal((await loadNodeModules({ vfs, packageManager: 'pnpm', libc })).stats.projects, 1, libc)))
  t.assert.equal((await buildVfsBundle({ vfs, packageManager: 'pnpm', libc: 'musl', entries: ['src/a.js'] })).bundle.sources.has('src/a.js'), true)
  const otherOs = process.platform === 'darwin' ? 'linux' : 'darwin'
  t.assert.equal((await loadNodeModules({ vfs, packageManager: 'pnpm', os: otherOs, cpu: 'arm64' })).stats.projects, 1)
  t.assert.equal(getReport.mock.callCount(), 0, 'a given libc, or another os, is not detected')
  await loadNodeModules({ vfs, packageManager: 'pnpm' })
  t.assert.equal(getReport.mock.callCount(), process.platform === 'linux' ? 1 : 0, 'none given: this machine\'s')
})

test('os and cpu are checked, and taken by pnpm and yarn 1 alike', async (t) => {
  const vfs = project()
  await t.assert.rejects(loadNodeModules({ vfs, packageManager: 'pnpm', os: '' }), /^TypeError: loadNodeModules: os must be a non-empty string/u)
  await t.assert.rejects(buildVfsBundle({ vfs, packageManager: 'pnpm', cpu: 64, entries: ['src/a.js'] }), /^TypeError: buildVfsBundle: cpu must be a non-empty string/u)
  const yarn = new Vfs()
  yarn.writeFile('/package.json', '{"name":"p","version":"1.0.0"}\n')
  yarn.writeFile('/yarn.lock', yarnLockfile)
  // yarn 1 matches no package's libc, so one given is no error and changes nothing.
  t.assert.equal((await loadNodeModules({ vfs: yarn, packageManager: 'yarn1', os: 'linux', cpu: 'x64', libc: 'musl' })).root, '/')
})
